insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance', 'Mendelian inheritance (also known as Mendelism) is a type of biological inheritance following the principles originally proposed by Gregor Mendel in 1865 and 1866, re-discovered in 1900 by Hugo de Vries and Carl Correns, and later popularized by William Bateson. Its defining characteristic is heavy association with a singular gene. The principles were initially controversial. When Mendel''s theories were integrated with the Boveri–Sutton chromosome theory of inheritance by Thomas Hunt Morgan in 1915, they became the core of classical genetics. Ronald Fisher combined these ideas with the theory of natural selection in his 1930 book The Genetical Theory of Natural Selection, putting evolution onto a mathematical footing and forming the basis for population genetics within the modern evolutionary synthesis.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Mendelian inheritance (also known as Mendelism) is a type of biological inheritance following the principles originally proposed by Gregor Mendel in 1865 and 1866, re-discovered in 1900 by Hugo de Vries and Carl Correns, and later popularized by William Bateson. Its defining characteristic is heavy association with a singular gene. The principles were initially controversial. When Mendel''s theories were integrated with the Boveri–Sutton chromosome theory of inheritance by Thomas Hunt Morgan in 1915, they became the core of classical genetics. Ronald Fisher combined these ideas with the theory of natural selection in his 1930 book The Genetical Theory of Natural Selection, putting evolution onto a mathematical footing and forming the basis for population genetics within the modern evolutionary synthesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Punnett squares', 'Punnett squares are a well known genetics tool that was created by an English geneticist, Reginald Punnett, which can visually demonstrate all the possible genotypes that an offspring can receive, given the genotypes of their parents. Each parent carries two alleles, which can be shown on the top and the side of the chart, and each contribute one of them towards reproduction at a time. Each of the squares in the middle demonstrates the number of times each pairing of parental alleles could combine to make potential offspring. Using probabilities, one can then determine which genotypes the parents can create, and at what frequencies they can be created. For example, if two parents both have a heterozygous genotype, then there would be a 50% chance for their offspring to have the same genotype, and a 50% chance they would have a homozygous genotype. Since they could possibly contribute two identical alleles, the 50% would be halved to 25% to account for each type of homozygote, whether this was a homozygous dominant genotype, or a homozygous recessive genotype.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Punnett squares are a well known genetics tool that was created by an English geneticist, Reginald Punnett, which can visually demonstrate all the possible genotypes that an offspring can receive, given the genotypes of their parents. Each parent carries two alleles, which can be shown on the top and the side of the chart, and each contribute one of them towards reproduction at a time. Each of the squares in the middle demonstrates the number of times each pairing of parental alleles could combine to make potential offspring. Using probabilities, one can then determine which genotypes the parents can create, and at what frequencies they can be created. For example, if two parents both have a heterozygous genotype, then there would be a 50% chance for their offspring to have the same genotype, and a 50% chance they would have a homozygous genotype. Since they could possibly contribute two identical alleles, the 50% would be halved to 25% to account for each type of homozygote, whether this was a homozygous dominant genotype, or a homozygous recessive genotype.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Pedigrees', 'Pedigrees are visual tree like representations that demonstrate exactly how alleles are being passed from past generations to future ones. They also provide a diagram displaying each individual that carries a desired allele, and exactly which side of inheritance it was received from, whether it was from their mother''s side or their father''s side. Pedigrees can also be used to aid researchers in determining the inheritance pattern for the desired allele, because they share information such as the gender of all individuals, the phenotype, a predicted genotype, the potential sources for the alleles, and also based its history, how it could continue to spread in the future generations to come. By using pedigrees, scientists have been able to find ways to control the flow of alleles over time, so that alleles that act problematic can be resolved upon discovery.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Pedigrees are visual tree like representations that demonstrate exactly how alleles are being passed from past generations to future ones. They also provide a diagram displaying each individual that carries a desired allele, and exactly which side of inheritance it was received from, whether it was from their mother''s side or their father''s side. Pedigrees can also be used to aid researchers in determining the inheritance pattern for the desired allele, because they share information such as the gender of all individuals, the phenotype, a predicted genotype, the potential sources for the alleles, and also based its history, how it could continue to spread in the future generations to come. By using pedigrees, scientists have been able to find ways to control the flow of alleles over time, so that alleles that act problematic can be resolved upon discovery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Mendel''s genetic discoveries', 'Five parts of Mendel''s discoveries were an important divergence from the common theories at the time and were the prerequisite for the establishment of his rules. Characters are unitary, that is, they are discrete e.g.: purple vs. white, tall vs. dwarf. There is no medium-sized plant or light purple flower. Genetic characteristics have alternate forms, each inherited from one of two parents. Today these are called alleles. One allele is dominant over the other. The phenotype reflects the dominant allele. Gametes are created by random segregation. Heterozygotic individuals produce gametes with an equal frequency of the two alleles. According to customary terminology, the principles of inheritance discovered by Gregor Mendel are here referred to as Mendelian laws, although today''s geneticists also speak of Mendelian rules or Mendelian principles, as there are many exceptions summarized under the collective term Non-Mendelian inheritance. The laws were initially formulated by the geneticist Thomas Hunt Morgan in 1916. Form of the ripe seeds (round or roundish, surface shallow or wrinkled) Colour of the seed–coat (white, gray, or brown, with or without violet spotting) Form of the ripe pods (simply inflated, not contracted, or constricted between the seeds and wrinkled)', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Five parts of Mendel''s discoveries were an important divergence from the common theories at the time and were the prerequisite for the establishment of his rules. Characters are unitary, that is, they are discrete e.g.: purple vs. white, tall vs. dwarf. There is no medium-sized plant or light purple flower. Genetic characteristics have alternate forms, each inherited from one of two parents. Today these are called alleles. One allele is dominant over the other. The phenotype reflects the dominant allele. Gametes are created by random segregation. Heterozygotic individuals produce gametes with an equal frequency of the two alleles. According to customary terminology, the principles of inheritance discovered by Gregor Mendel are here referred to as Mendelian laws, although today''s geneticists also speak of Mendelian rules or Mendelian principles, as there are many exceptions summarized under the collective term Non-Mendelian inheritance. The laws were initially formulated by the geneticist Thomas Hunt Morgan in 1916. Form of the ripe seeds (round or roundish, surface shallow or wrinkled) Colour of the seed–coat (white, gray, or brown, with or without violet spotting) Form of the ripe pods (simply inflated, not contracted, or constricted between the seeds and wrinkled)');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Mendel''s genetic discoveries', 'When he crossed purebred white flower and purple flower pea plants (the parental or P generation) by artificial pollination, the resulting flower colour was not a blend. Rather than being a mix of the two, the offspring in the first generation (F1-generation) were all purple-flowered. Therefore, he called this biological trait dominant. When he allowed self-fertilization in the uniform looking F1-generation, he obtained both colours in the F2 generation with a purple flower to white flower ratio of 3: 1. In some of the other characters also one of the traits was dominant. He then conceived the idea of heredity units, which he called "factors". Mendel found that there are alternative forms of factors—now called genes—that account for variations in inherited characteristics. For example, the gene for flower color in pea plants exists in two forms, one for purple and the other for white. The alternative "forms" are now called alleles. For each trait, an organism inherits two alleles, one from each parent. These alleles may be the same or different. An organism that has two identical alleles for a gene is said to be homozygous for that gene (and is called a homozygote). An organism that has two different alleles for a gene is said to be heterozygous for that gene (and is called a heterozygote).', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'When he crossed purebred white flower and purple flower pea plants (the parental or P generation) by artificial pollination, the resulting flower colour was not a blend. Rather than being a mix of the two, the offspring in the first generation (F1-generation) were all purple-flowered. Therefore, he called this biological trait dominant. When he allowed self-fertilization in the uniform looking F1-generation, he obtained both colours in the F2 generation with a purple flower to white flower ratio of 3: 1. In some of the other characters also one of the traits was dominant. He then conceived the idea of heredity units, which he called "factors". Mendel found that there are alternative forms of factors—now called genes—that account for variations in inherited characteristics. For example, the gene for flower color in pea plants exists in two forms, one for purple and the other for white. The alternative "forms" are now called alleles. For each trait, an organism inherits two alleles, one from each parent. These alleles may be the same or different. An organism that has two identical alleles for a gene is said to be homozygous for that gene (and is called a homozygote). An organism that has two different alleles for a gene is said to be heterozygous for that gene (and is called a heterozygote).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Mendel''s genetic discoveries', 'Mendel hypothesized that allele pairs separate randomly, or segregate, from each other during the production of the gametes in the seed plant (egg cell) and the pollen plant (sperm). Because allele pairs separate during gamete production, a sperm or egg carries only one allele for each inherited trait. When sperm and egg unite at fertilization, each contributes its allele, restoring the paired condition in the offspring. Mendel also found that each pair of alleles segregates independently of the other pairs of alleles during gamete formation. The genotype of an individual is made up of the many alleles it possesses. The phenotype is the result of the expression of all characteristics that are genetically determined by its alleles as well as by its environment. The presence of an allele does not mean that the trait will be expressed in the individual that possesses it. If the two alleles of an inherited pair differ (the heterozygous condition), then one determines the organism''s appearance and is called the dominant allele; the other has no noticeable effect on the organism''s appearance and is called the recessive allele.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Mendel hypothesized that allele pairs separate randomly, or segregate, from each other during the production of the gametes in the seed plant (egg cell) and the pollen plant (sperm). Because allele pairs separate during gamete production, a sperm or egg carries only one allele for each inherited trait. When sperm and egg unite at fertilization, each contributes its allele, restoring the paired condition in the offspring. Mendel also found that each pair of alleles segregates independently of the other pairs of alleles during gamete formation. The genotype of an individual is made up of the many alleles it possesses. The phenotype is the result of the expression of all characteristics that are genetically determined by its alleles as well as by its environment. The presence of an allele does not mean that the trait will be expressed in the individual that possesses it. If the two alleles of an inherited pair differ (the heterozygous condition), then one determines the organism''s appearance and is called the dominant allele; the other has no noticeable effect on the organism''s appearance and is called the recessive allele.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Law of dominance and uniformity', 'If two parents are mated with each other who differ in one genetic characteristic for which they are both homozygous (each pure-bred), all offspring in the first generation (F1) are equal to the examined characteristic in genotype and phenotype showing the dominant trait. This uniformity rule or reciprocity rule applies to all individuals of the F1-generation. The principle of dominant inheritance discovered by Mendel states that in a heterozygote the dominant allele will cause the recessive allele to be "masked": that is, not expressed in the phenotype. Only if an individual is homozygous with respect to the recessive allele will the recessive trait be expressed. Therefore, a cross between a homozygous dominant and a homozygous recessive organism yields a heterozygous organism whose phenotype displays only the dominant trait. The F1 offspring of Mendel''s pea crosses always looked like one of the two parental varieties. In this situation of "complete dominance", the dominant allele had the same phenotypic effect whether present in one or two copies.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'If two parents are mated with each other who differ in one genetic characteristic for which they are both homozygous (each pure-bred), all offspring in the first generation (F1) are equal to the examined characteristic in genotype and phenotype showing the dominant trait. This uniformity rule or reciprocity rule applies to all individuals of the F1-generation. The principle of dominant inheritance discovered by Mendel states that in a heterozygote the dominant allele will cause the recessive allele to be "masked": that is, not expressed in the phenotype. Only if an individual is homozygous with respect to the recessive allele will the recessive trait be expressed. Therefore, a cross between a homozygous dominant and a homozygous recessive organism yields a heterozygous organism whose phenotype displays only the dominant trait. The F1 offspring of Mendel''s pea crosses always looked like one of the two parental varieties. In this situation of "complete dominance", the dominant allele had the same phenotypic effect whether present in one or two copies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Mendelian inheritance: Law of dominance and uniformity', 'But for some characteristics, the F1 hybrids have an appearance in between the phenotypes of the two parental varieties. A cross between two four o''clock (Mirabilis jalapa) plants shows an exception to Mendel''s principle, called incomplete dominance. Flowers of heterozygous plants have a phenotype somewhere between the two homozygous genotypes. In cases of intermediate inheritance (incomplete dominance) in the F1-generation Mendel''s principle of uniformity in genotype and phenotype applies as well. Research about intermediate inheritance was done by other scientists. The first was Carl Correns with his studies about Mirabilis jalapa.', 'Wikipedia: Mendelian inheritance', 'https://en.wikipedia.org/w/index.php?title=Mendelian_inheritance&oldid=1379866501', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'But for some characteristics, the F1 hybrids have an appearance in between the phenotypes of the two parental varieties. A cross between two four o''clock (Mirabilis jalapa) plants shows an exception to Mendel''s principle, called incomplete dominance. Flowers of heterozygous plants have a phenotype somewhere between the two homozygous genotypes. In cases of intermediate inheritance (incomplete dominance) in the F1-generation Mendel''s principle of uniformity in genotype and phenotype applies as well. Research about intermediate inheritance was done by other scientists. The first was Carl Correns with his studies about Mirabilis jalapa.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics)', 'In genetics, dominance is the phenomenon of one variant (allele) of a gene on a chromosome masking or overriding the effect of a different variant of the same gene on the other copy of the chromosome. The masking or overriding variant is said to be dominant and the other recessive. This state of having two different variants of the same gene, one on each copy of the chromosome, is originally caused by a mutation in one of the genes, either new (de novo) or inherited. The terms autosomal dominant and autosomal recessive are used to describe gene variants on non-sex chromosomes (autosomes) and their associated traits, while those on sex chromosomes (allosomes) are termed X-linked dominant, X-linked recessive or Y-linked; these have an inheritance and presentation pattern that depends on the sex of both the parent and the child (see Sex linkage). Since there is only one Y chromosome, Y-linked traits cannot be dominant or recessive. Additionally, there are other forms of dominance, such as incomplete dominance, in which a gene variant has a partial effect compared to when it is present on both chromosomes, and co-dominance, in which different variants on each chromosome both show their associated traits.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'In genetics, dominance is the phenomenon of one variant (allele) of a gene on a chromosome masking or overriding the effect of a different variant of the same gene on the other copy of the chromosome. The masking or overriding variant is said to be dominant and the other recessive. This state of having two different variants of the same gene, one on each copy of the chromosome, is originally caused by a mutation in one of the genes, either new (de novo) or inherited. The terms autosomal dominant and autosomal recessive are used to describe gene variants on non-sex chromosomes (autosomes) and their associated traits, while those on sex chromosomes (allosomes) are termed X-linked dominant, X-linked recessive or Y-linked; these have an inheritance and presentation pattern that depends on the sex of both the parent and the child (see Sex linkage). Since there is only one Y chromosome, Y-linked traits cannot be dominant or recessive. Additionally, there are other forms of dominance, such as incomplete dominance, in which a gene variant has a partial effect compared to when it is present on both chromosomes, and co-dominance, in which different variants on each chromosome both show their associated traits.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics)', 'Dominance is a key concept studied by Gregor Mendel in Mendelian inheritance and classical genetics. Letters and Punnett squares are used to demonstrate the principles of dominance in teaching, and the upper-case letters are used to denote dominant alleles and lower-case letters are used for recessive alleles. An often quoted example of dominance is the inheritance of seed shape in peas. Peas may be round, associated with allele R, or wrinkled, associated with allele r. In this case, three combinations of alleles (genotypes) are possible: RR, Rr, and rr. The RR (homozygous) individuals have round peas, and the rr (homozygous) individuals have wrinkled peas. In Rr (heterozygous) individuals, the R allele masks the presence of the r allele, so these individuals also have round peas. Thus, allele R is dominant over allele r, and allele r is recessive to allele R.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Dominance is a key concept studied by Gregor Mendel in Mendelian inheritance and classical genetics. Letters and Punnett squares are used to demonstrate the principles of dominance in teaching, and the upper-case letters are used to denote dominant alleles and lower-case letters are used for recessive alleles. An often quoted example of dominance is the inheritance of seed shape in peas. Peas may be round, associated with allele R, or wrinkled, associated with allele r. In this case, three combinations of alleles (genotypes) are possible: RR, Rr, and rr. The RR (homozygous) individuals have round peas, and the rr (homozygous) individuals have wrinkled peas. In Rr (heterozygous) individuals, the R allele masks the presence of the r allele, so these individuals also have round peas. Thus, allele R is dominant over allele r, and allele r is recessive to allele R.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics)', 'Dominance is not inherent to an allele or its traits (phenotype). It is a strictly relative effect between two alleles of a given gene of any function; one allele can be dominant over a second allele of the same gene, recessive to a third, and co-dominant with a fourth. Additionally, one allele may be dominant for one trait but not others. Dominance differs from epistasis, the phenomenon of an allele of one gene masking the effect of alleles of a different gene.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Dominance is not inherent to an allele or its traits (phenotype). It is a strictly relative effect between two alleles of a given gene of any function; one allele can be dominant over a second allele of the same gene, recessive to a third, and co-dominant with a fourth. Additionally, one allele may be dominant for one trait but not others. Dominance differs from epistasis, the phenomenon of an allele of one gene masking the effect of alleles of a different gene.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics): Background', 'Gregor Johann Mendel, "The Father of Genetics", promulgated the idea of dominance in the 1860s. However, it was not widely known until the early twentieth century. Mendel observed that, for a variety of traits of garden peas having to do with the appearance of seeds, seed pods, and plants, there were two discrete phenotypes, such as round versus wrinkled seeds, yellow versus green seeds, red versus white flowers or tall versus short plants. When bred separately, the plants always produced the same phenotypes, generation after generation. However, when lines with different phenotypes were crossed (interbred), one and only one of the parental phenotypes showed up in the offspring (green, round, red, or tall). However, when these hybrid plants were crossed, the offspring plants showed the two original phenotypes, in a characteristic 3:1 ratio, the more common phenotype being that of the parental hybrid plants. Mendel reasoned that each parent in the first cross was a homozygote for different alleles (one parent AA and the other parent aa), that each contributed one allele to the offspring, with the result that all of these hybrids were heterozygotes (Aa), and that one of the two alleles in the hybrid cross dominated expression of the other: A masked a. The final cross between two heterozygotes (Aa X Aa) would produce AA, Aa, and aa offspring in a 1:2:1 genotype ratio with the first two classes showing the (A) phenotype, and the last showing the (a) phenotype, thereby producing the 3:1 phenotype ratio.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Gregor Johann Mendel, "The Father of Genetics", promulgated the idea of dominance in the 1860s. However, it was not widely known until the early twentieth century. Mendel observed that, for a variety of traits of garden peas having to do with the appearance of seeds, seed pods, and plants, there were two discrete phenotypes, such as round versus wrinkled seeds, yellow versus green seeds, red versus white flowers or tall versus short plants. When bred separately, the plants always produced the same phenotypes, generation after generation. However, when lines with different phenotypes were crossed (interbred), one and only one of the parental phenotypes showed up in the offspring (green, round, red, or tall). However, when these hybrid plants were crossed, the offspring plants showed the two original phenotypes, in a characteristic 3:1 ratio, the more common phenotype being that of the parental hybrid plants. Mendel reasoned that each parent in the first cross was a homozygote for different alleles (one parent AA and the other parent aa), that each contributed one allele to the offspring, with the result that all of these hybrids were heterozygotes (Aa), and that one of the two alleles in the hybrid cross dominated expression of the other: A masked a. The final cross between two heterozygotes (Aa X Aa) would produce AA, Aa, and aa offspring in a 1:2:1 genotype ratio with the first two classes showing the (A) phenotype, and the last showing the (a) phenotype, thereby producing the 3:1 phenotype ratio.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics): Background', 'Mendel did not use the terms gene, allele, phenotype, genotype, homozygote, and heterozygote, all of which were introduced later. He did introduce the notation of capital and lowercase letters for dominant and recessive alleles, respectively, still in use today. In 1928, British population geneticist Ronald Fisher proposed that dominance acted based on natural selection through the contribution of modifier genes. In 1929, American geneticist Sewall Wright responded by stating that dominance is simply a physiological consequence of metabolic pathways and the relative necessity of the gene involved.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Mendel did not use the terms gene, allele, phenotype, genotype, homozygote, and heterozygote, all of which were introduced later. He did introduce the notation of capital and lowercase letters for dominant and recessive alleles, respectively, still in use today. In 1928, British population geneticist Ronald Fisher proposed that dominance acted based on natural selection through the contribution of modifier genes. In 1929, American geneticist Sewall Wright responded by stating that dominance is simply a physiological consequence of metabolic pathways and the relative necessity of the gene involved.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics): Complete dominance (Mendelian)', 'In complete dominance, the effect of one allele in a heterozygous genotype completely masks the effect of the other. The allele that masks are considered dominant to the other allele, and the masked allele is considered recessive. When we only look at one trait determined by one pair of genes, we call it monohybrid inheritance. If the crossing is done between parents (P-generation, F0-generation) who are homozygote dominant and homozygote recessive, the offspring (F1-generation) will always have the heterozygote genotype and always present the phenotype associated with the dominant gene.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'In complete dominance, the effect of one allele in a heterozygous genotype completely masks the effect of the other. The allele that masks are considered dominant to the other allele, and the masked allele is considered recessive. When we only look at one trait determined by one pair of genes, we call it monohybrid inheritance. If the crossing is done between parents (P-generation, F0-generation) who are homozygote dominant and homozygote recessive, the offspring (F1-generation) will always have the heterozygote genotype and always present the phenotype associated with the dominant gene.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics): Complete dominance (Mendelian)', 'However, if the F1-generation is further crossed with the F1-generation (heterozygote crossed with heterozygote) the offspring (F2-generation) will present the phenotype associated with the dominant gene ¾ times. Although heterozygote monohybrid crossing can result in two phenotype variants, it can result in three genotype variants - homozygote dominant, heterozygote and homozygote recessive, respectively.In dihybrid inheritance we look at the inheritance of two pairs of genes simultaneously. Assuming here that the two pairs of genes are located at non-homologous chromosomes, such that they are not coupled genes (see genetic linkage) but instead inherited independently. Consider now the cross between parents (P-generation) of genotypes homozygote dominant and recessive, respectively. The offspring (F1-generation) will always heterozygous and present the phenotype associated with the dominant allele variant. However, when crossing the F1-generation there are four possible phenotypic possibilities and the phenotypical ratio for the F2-generation will always be 9:3:3:1.', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'However, if the F1-generation is further crossed with the F1-generation (heterozygote crossed with heterozygote) the offspring (F2-generation) will present the phenotype associated with the dominant gene ¾ times. Although heterozygote monohybrid crossing can result in two phenotype variants, it can result in three genotype variants - homozygote dominant, heterozygote and homozygote recessive, respectively.In dihybrid inheritance we look at the inheritance of two pairs of genes simultaneously. Assuming here that the two pairs of genes are located at non-homologous chromosomes, such that they are not coupled genes (see genetic linkage) but instead inherited independently. Consider now the cross between parents (P-generation) of genotypes homozygote dominant and recessive, respectively. The offspring (F1-generation) will always heterozygous and present the phenotype associated with the dominant allele variant. However, when crossing the F1-generation there are four possible phenotypic possibilities and the phenotypical ratio for the F2-generation will always be 9:3:3:1.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Dominance (genetics): Incomplete dominance (non-Mendelian)', 'Incomplete dominance (also called partial dominance, semi-dominance, intermediate inheritance, or occasionally incorrectly co-dominance in reptile genetics) occurs when the phenotype of the heterozygous genotype is distinct from and often intermediate to the phenotypes of the homozygous genotypes. The phenotypic result often appears as a blended form of characteristics in the heterozygous state. For example, the snapdragon flower color is homozygous for either red or white. When the red homozygous flower is paired with the white homozygous flower, the result yields a pink snapdragon flower. The pink snapdragon is the result of incomplete dominance. A similar type of incomplete dominance is found in the four o''clock plant wherein pink color is produced when true-bred parents of white and red flowers are crossed. In quantitative genetics, where phenotypes are measured and treated numerically, if a heterozygote''s phenotype is exactly between (numerically) that of the two homozygotes, the phenotype is said to exhibit no dominance at all, i.e. dominance exists only when the heterozygote''s phenotype measure lies closer to one homozygote than the other. When plants of the F1 generation are self-pollinated, the phenotypic and genotypic ratio of the F2 generation will be 1:2:1 (Red:Pink:White).', 'Wikipedia: Dominance (genetics)', 'https://en.wikipedia.org/w/index.php?title=Dominance_(genetics)&oldid=1380420266', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Incomplete dominance (also called partial dominance, semi-dominance, intermediate inheritance, or occasionally incorrectly co-dominance in reptile genetics) occurs when the phenotype of the heterozygous genotype is distinct from and often intermediate to the phenotypes of the homozygous genotypes. The phenotypic result often appears as a blended form of characteristics in the heterozygous state. For example, the snapdragon flower color is homozygous for either red or white. When the red homozygous flower is paired with the white homozygous flower, the result yields a pink snapdragon flower. The pink snapdragon is the result of incomplete dominance. A similar type of incomplete dominance is found in the four o''clock plant wherein pink color is produced when true-bred parents of white and red flowers are crossed. In quantitative genetics, where phenotypes are measured and treated numerically, if a heterozygote''s phenotype is exactly between (numerically) that of the two homozygotes, the phenotype is said to exhibit no dominance at all, i.e. dominance exists only when the heterozygote''s phenotype measure lies closer to one homozygote than the other. When plants of the F1 generation are self-pollinated, the phenotypic and genotypic ratio of the F2 generation will be 1:2:1 (Red:Pink:White).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage', 'Genetic linkage is the tendency of DNA sequences that are close together on a chromosome to be inherited together during the meiosis phase of sexual reproduction. Two genetic markers that are physically near to each other are unlikely to be separated onto different chromatids during chromosomal crossover, and are therefore said to be more linked than markers that are far apart. In other words, the nearer two genes are on a chromosome, the lower the chance of recombination between them, and the more likely they are to be inherited together. Markers on different chromosomes are perfectly unlinked, although the penetrance of potentially deleterious alleles may be influenced by the presence of other alleles, and these other alleles may be located on other chromosomes than that on which a particular potentially deleterious allele is located. Genetic linkage is the most prominent exception to Gregor Mendel''s Law of Independent Assortment. The first experiment to demonstrate linkage was carried out in 1905. At the time, the reason why certain traits tend to be inherited together was unknown. Later work revealed that genes are physical structures related by physical distance.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Genetic linkage is the tendency of DNA sequences that are close together on a chromosome to be inherited together during the meiosis phase of sexual reproduction. Two genetic markers that are physically near to each other are unlikely to be separated onto different chromatids during chromosomal crossover, and are therefore said to be more linked than markers that are far apart. In other words, the nearer two genes are on a chromosome, the lower the chance of recombination between them, and the more likely they are to be inherited together. Markers on different chromosomes are perfectly unlinked, although the penetrance of potentially deleterious alleles may be influenced by the presence of other alleles, and these other alleles may be located on other chromosomes than that on which a particular potentially deleterious allele is located. Genetic linkage is the most prominent exception to Gregor Mendel''s Law of Independent Assortment. The first experiment to demonstrate linkage was carried out in 1905. At the time, the reason why certain traits tend to be inherited together was unknown. Later work revealed that genes are physical structures related by physical distance.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage', 'The typical unit of genetic linkage is the centimorgan (cM). A distance of 1 cM between two markers means that the markers are separated to different chromosomes on average once per 100 meiotic product, thus once per 50 meioses.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'The typical unit of genetic linkage is the centimorgan (cM). A distance of 1 cM between two markers means that the markers are separated to different chromosomes on average once per 100 meiotic product, thus once per 50 meioses.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Discovery', 'Gregor Mendel''s Law of Independent Assortment states that every trait is inherited independently of every other trait. But shortly after Mendel''s work was rediscovered, exceptions to this rule were found. In 1905, the British geneticists William Bateson, Edith Rebecca Saunders and Reginald Punnett cross-bred pea plants in experiments similar to Mendel''s. They were interested in trait inheritance in the sweet pea and were studying two genes—the gene for flower colour (P, purple, and p, red) and the gene affecting the shape of pollen grains (L, long, and l, round). They crossed the pure lines PPLL and ppll and then self-crossed the resulting PpLl lines. According to Mendelian genetics, the expected phenotypes would occur in a 9:3:3:1 ratio of PL:Pl:pL:pl. To their surprise, they observed an increased frequency of PL and pl and a decreased frequency of Pl and pL:', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Gregor Mendel''s Law of Independent Assortment states that every trait is inherited independently of every other trait. But shortly after Mendel''s work was rediscovered, exceptions to this rule were found. In 1905, the British geneticists William Bateson, Edith Rebecca Saunders and Reginald Punnett cross-bred pea plants in experiments similar to Mendel''s. They were interested in trait inheritance in the sweet pea and were studying two genes—the gene for flower colour (P, purple, and p, red) and the gene affecting the shape of pollen grains (L, long, and l, round). They crossed the pure lines PPLL and ppll and then self-crossed the resulting PpLl lines. According to Mendelian genetics, the expected phenotypes would occur in a 9:3:3:1 ratio of PL:Pl:pL:pl. To their surprise, they observed an increased frequency of PL and pl and a decreased frequency of Pl and pL:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Discovery', 'Their experiment revealed linkage between the P and L alleles and the p and l alleles. The frequency of P occurring together with L and p occurring together with l is greater than that of the recombinant Pl and pL. The recombination frequency is more difficult to compute in an F2 cross than a backcross, but the lack of fit between observed and expected numbers of progeny in the above table indicate it is less than 50%. This indicated that two factors interacted in some way to create this difference by masking the appearance of the other two phenotypes. This led to the conclusion that some traits are related to each other because of their near proximity to each other on a chromosome. The understanding of linkage was expanded by the work of Thomas Hunt Morgan. Morgan''s observation that the amount of crossing over between linked genes differs led to the idea that crossover frequency might indicate the distance separating genes on the chromosome. The centimorgan, which expresses the frequency of crossing over, is named in his honour.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Their experiment revealed linkage between the P and L alleles and the p and l alleles. The frequency of P occurring together with L and p occurring together with l is greater than that of the recombinant Pl and pL. The recombination frequency is more difficult to compute in an F2 cross than a backcross, but the lack of fit between observed and expected numbers of progeny in the above table indicate it is less than 50%. This indicated that two factors interacted in some way to create this difference by masking the appearance of the other two phenotypes. This led to the conclusion that some traits are related to each other because of their near proximity to each other on a chromosome. The understanding of linkage was expanded by the work of Thomas Hunt Morgan. Morgan''s observation that the amount of crossing over between linked genes differs led to the idea that crossover frequency might indicate the distance separating genes on the chromosome. The centimorgan, which expresses the frequency of crossing over, is named in his honour.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Linkage map', 'A linkage map (also known as a genetic map) is a table for a species or experimental population that shows the position of its known genes or genetic markers relative to each other in terms of recombination frequency, rather than a specific physical distance along each chromosome. Linkage maps were first developed by Alfred Sturtevant, a student of Thomas Hunt Morgan. A linkage map is a map based on the frequencies of recombination between markers during crossover of homologous chromosomes. The greater the frequency of recombination (segregation) between two genetic markers, the further apart they are assumed to be. Conversely, the lower the frequency of recombination between the markers, the smaller the physical distance between them. Historically, the markers originally used were detectable phenotypes (enzyme production, eye colour) derived from coding DNA sequences; eventually, confirmed or assumed noncoding DNA sequences such as microsatellites or those generating restriction fragment length polymorphisms (RFLPs) have been used.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'A linkage map (also known as a genetic map) is a table for a species or experimental population that shows the position of its known genes or genetic markers relative to each other in terms of recombination frequency, rather than a specific physical distance along each chromosome. Linkage maps were first developed by Alfred Sturtevant, a student of Thomas Hunt Morgan. A linkage map is a map based on the frequencies of recombination between markers during crossover of homologous chromosomes. The greater the frequency of recombination (segregation) between two genetic markers, the further apart they are assumed to be. Conversely, the lower the frequency of recombination between the markers, the smaller the physical distance between them. Historically, the markers originally used were detectable phenotypes (enzyme production, eye colour) derived from coding DNA sequences; eventually, confirmed or assumed noncoding DNA sequences such as microsatellites or those generating restriction fragment length polymorphisms (RFLPs) have been used.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Linkage map', 'Linkage maps help researchers to locate other markers, such as other genes by testing for genetic linkage of the already known markers. In the early stages of developing a linkage map, the data are used to assemble linkage groups, a set of genes which are known to be linked. As knowledge advances, more markers can be added to a group, until the group covers an entire chromosome. For well-studied organisms the linkage groups correspond one-to-one with the chromosomes. A linkage map is not a physical map (such as a radiation reduced hybrid map) or gene map.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Linkage maps help researchers to locate other markers, such as other genes by testing for genetic linkage of the already known markers. In the early stages of developing a linkage map, the data are used to assemble linkage groups, a set of genes which are known to be linked. As knowledge advances, more markers can be added to a group, until the group covers an entire chromosome. For well-studied organisms the linkage groups correspond one-to-one with the chromosomes. A linkage map is not a physical map (such as a radiation reduced hybrid map) or gene map.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Linkage analysis', 'Linkage analysis is a genetic method that searches for chromosomal segments that cosegregate with the ailment phenotype through families. It can be used to map genes for both binary and quantitative traits. Linkage analysis may be either parametric (if we know the relationship between phenotypic and genetic similarity) or non-parametric. Parametric linkage analysis is the traditional approach, whereby the probability that a gene important for a disease is linked to a genetic marker is studied through the LOD score, which assesses the probability that a given pedigree, where the disease and the marker are cosegregating, is due to the existence of linkage (with a given linkage value) or to chance. Non-parametric linkage analysis, in turn, studies the probability of an allele being identical by descent with itself.', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Linkage analysis is a genetic method that searches for chromosomal segments that cosegregate with the ailment phenotype through families. It can be used to map genes for both binary and quantitative traits. Linkage analysis may be either parametric (if we know the relationship between phenotypic and genetic similarity) or non-parametric. Parametric linkage analysis is the traditional approach, whereby the probability that a gene important for a disease is linked to a genetic marker is studied through the LOD score, which assesses the probability that a given pedigree, where the disease and the marker are cosegregating, is due to the existence of linkage (with a given linkage value) or to chance. Non-parametric linkage analysis, in turn, studies the probability of an allele being identical by descent with itself.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic linkage: Parametric linkage analysis', 'The LOD score (logarithm (base 10) of odds), developed by Newton Morton, is a statistical test often used for linkage analysis in human, animal, and plant populations. The LOD score compares the likelihood of obtaining the test data if the two loci are indeed linked, to the likelihood of observing the same data purely by chance (that is, it is (the log of) the likelihood ratio). Thus, one can add the LOD score to the log odds of the prior probability for the hypothesis to update it to the posterior log odds as prescribed by Bayes'' law. That is, LOD scores are precisely the strength of evidence (in base 10 instead of bits) for linkage of an amount equal to the observed amount (essentially, a maximum likelihood or maximum a posteriori value). Positive LOD scores favour the presence of linkage, whereas negative LOD scores indicate that linkage is less likely. Computerised LOD score analysis is a simple way to analyse complex family pedigrees in order to determine the linkage between Mendelian traits (or between a trait and a marker, or two markers). The method is described in greater detail by Strachan and Read.[1] Briefly, it works as follows: The estimate with the highest LOD score will be considered the best estimate', 'Wikipedia: Genetic linkage', 'https://en.wikipedia.org/w/index.php?title=Genetic_linkage&oldid=1377987233', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'The LOD score (logarithm (base 10) of odds), developed by Newton Morton, is a statistical test often used for linkage analysis in human, animal, and plant populations. The LOD score compares the likelihood of obtaining the test data if the two loci are indeed linked, to the likelihood of observing the same data purely by chance (that is, it is (the log of) the likelihood ratio). Thus, one can add the LOD score to the log odds of the prior probability for the hypothesis to update it to the posterior log odds as prescribed by Bayes'' law. That is, LOD scores are precisely the strength of evidence (in base 10 instead of bits) for linkage of an amount equal to the observed amount (essentially, a maximum likelihood or maximum a posteriori value). Positive LOD scores favour the presence of linkage, whereas negative LOD scores indicate that linkage is less likely. Computerised LOD score analysis is a simple way to analyse complex family pedigrees in order to determine the linkage between Mendelian traits (or between a trait and a marker, or two markers). The method is described in greater detail by Strachan and Read.[1] Briefly, it works as follows: The estimate with the highest LOD score will be considered the best estimate');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle', 'In population genetics, the Hardy–Weinberg principle, also known as the Hardy–Weinberg equilibrium, model, theorem, or law, states that allele and genotype frequencies in a population will remain constant from generation to generation in the absence of other evolutionary influences. These influences include genetic drift, mate choice, assortative mating, natural selection, sexual selection, mutation, gene flow, meiotic drive, genetic hitchhiking, population bottleneck, founder effect, inbreeding, and outbreeding depression.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'In population genetics, the Hardy–Weinberg principle, also known as the Hardy–Weinberg equilibrium, model, theorem, or law, states that allele and genotype frequencies in a population will remain constant from generation to generation in the absence of other evolutionary influences. These influences include genetic drift, mate choice, assortative mating, natural selection, sexual selection, mutation, gene flow, meiotic drive, genetic hitchhiking, population bottleneck, founder effect, inbreeding, and outbreeding depression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Derivation', 'In the simplest case of a single locus with two alleles denoted A and a with frequencies f(A) = p and f(a) = q, respectively, the expected genotype frequencies under random mating are f(AA) = p2 for the AA homozygotes, f(aa) = q2 for the aa homozygotes, and f(Aa) = 2pq for the heterozygotes. In the absence of selection, mutation, genetic drift, or other forces, allele frequencies p and q are constant between generations, so equilibrium is reached. The principle is named after G. H. Hardy and Wilhelm Weinberg, who first demonstrated it mathematically. Hardy''s paper was focused on debunking the view that a dominant allele would automatically tend to increase in frequency (a view possibly based on a misinterpreted question at a lecture). Today, tests for Hardy–Weinberg genotype frequencies are used primarily to test for population stratification and other forms of non-random mating.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'In the simplest case of a single locus with two alleles denoted A and a with frequencies f(A) = p and f(a) = q, respectively, the expected genotype frequencies under random mating are f(AA) = p2 for the AA homozygotes, f(aa) = q2 for the aa homozygotes, and f(Aa) = 2pq for the heterozygotes. In the absence of selection, mutation, genetic drift, or other forces, allele frequencies p and q are constant between generations, so equilibrium is reached. The principle is named after G. H. Hardy and Wilhelm Weinberg, who first demonstrated it mathematically. Hardy''s paper was focused on debunking the view that a dominant allele would automatically tend to increase in frequency (a view possibly based on a misinterpreted question at a lecture). Today, tests for Hardy–Weinberg genotype frequencies are used primarily to test for population stratification and other forms of non-random mating.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Derivation', 'Consider a population of monoecious diploids, where each organism produces male and female gametes at equal frequency, and has two alleles at each gene locus. We assume that the population is so large that it can be treated as infinite. Organisms reproduce by random union of gametes (the "gene pool" population model). A locus in this population has two alleles, A and a, that occur with initial frequencies f0(A) = p and f0(a) = q, respectively. The allele frequencies at each generation are obtained by pooling together the alleles from each genotype of the same generation according to the expected contribution from the homozygote and heterozygote genotypes, which are 1 and 1/2, respectively: The different ways to form genotypes for the next generation can be shown in a Punnett square, where the proportion of each genotype is equal to the product of the row and column allele frequencies from the current generation. The sum of the entries is p2 + 2pq + q2 = 1, as the genotype frequencies must sum to one. Note again that as p + q = 1, the binomial expansion of (p + q)2 = p2 + 2pq + q2 = 1 gives the same relationships.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Consider a population of monoecious diploids, where each organism produces male and female gametes at equal frequency, and has two alleles at each gene locus. We assume that the population is so large that it can be treated as infinite. Organisms reproduce by random union of gametes (the "gene pool" population model). A locus in this population has two alleles, A and a, that occur with initial frequencies f0(A) = p and f0(a) = q, respectively. The allele frequencies at each generation are obtained by pooling together the alleles from each genotype of the same generation according to the expected contribution from the homozygote and heterozygote genotypes, which are 1 and 1/2, respectively: The different ways to form genotypes for the next generation can be shown in a Punnett square, where the proportion of each genotype is equal to the product of the row and column allele frequencies from the current generation. The sum of the entries is p2 + 2pq + q2 = 1, as the genotype frequencies must sum to one. Note again that as p + q = 1, the binomial expansion of (p + q)2 = p2 + 2pq + q2 = 1 gives the same relationships.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Derivation', 'Summing the elements of the Punnett square or the binomial expansion, we obtain the expected genotype proportions among the offspring after a single generation: These frequencies define the Hardy–Weinberg equilibrium. It should be mentioned that the genotype frequencies after the first generation need not equal the genotype frequencies from the initial generation, e.g. f1(AA) ≠ f0(AA). However, the genotype frequencies for all future times will equal the Hardy–Weinberg frequencies, e.g. ft(AA) = f1(AA) for t > 1. This follows since the genotype frequencies of the next generation depend only on the allele frequencies of the current generation which, as calculated by equations (1) and (2), are preserved from the initial generation: For the more general case of dioecious diploids [organisms are either male or female] that reproduce by random mating of individuals, it is necessary to calculate the genotype frequencies from the nine possible matings between each parental genotype (AA, Aa, and aa) in either sex, weighted by the expected genotype contributions of each such mating. Equivalently, one considers the six unique diploid–diploid combinations:', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Summing the elements of the Punnett square or the binomial expansion, we obtain the expected genotype proportions among the offspring after a single generation: These frequencies define the Hardy–Weinberg equilibrium. It should be mentioned that the genotype frequencies after the first generation need not equal the genotype frequencies from the initial generation, e.g. f1(AA) ≠ f0(AA). However, the genotype frequencies for all future times will equal the Hardy–Weinberg frequencies, e.g. ft(AA) = f1(AA) for t > 1. This follows since the genotype frequencies of the next generation depend only on the allele frequencies of the current generation which, as calculated by equations (1) and (2), are preserved from the initial generation: For the more general case of dioecious diploids [organisms are either male or female] that reproduce by random mating of individuals, it is necessary to calculate the genotype frequencies from the nine possible matings between each parental genotype (AA, Aa, and aa) in either sex, weighted by the expected genotype contributions of each such mating. Equivalently, one considers the six unique diploid–diploid combinations:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Derivation', 'and constructs a Punnett square for each, so as to calculate its contribution to the next generation''s genotypes. These contributions are weighted according to the probability of each diploid–diploid combination, which follows a multinomial distribution with k = 3. For example, the probability of the mating combination (AA,aa) is 2 ft(AA)ft(aa) and it can only result in the Aa genotype: [0,1,0]. Overall, the resulting genotype frequencies are calculated as: As before, one can show that the allele frequencies at time t + 1 equal those at time t, and so, are constant in time. Similarly, the genotype frequencies depend only on the allele frequencies, and so, after time t = 1 are also constant in time. If in either monoecious or dioecious organisms, either the allele or genotype proportions are initially unequal in either sex, it can be shown that constant proportions are obtained after one generation of random mating. If dioecious organisms are heterogametic and the gene locus is located on the X chromosome, it can be shown that if the allele frequencies are initially unequal in the two sexes [e.g., XX females and XY males, as in humans], f′(a) in the heterogametic sex ''chases'' f(a) in the homogametic sex of the previous generation, until an equilibrium is reached at the weighted average of the two initial frequencies.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'and constructs a Punnett square for each, so as to calculate its contribution to the next generation''s genotypes. These contributions are weighted according to the probability of each diploid–diploid combination, which follows a multinomial distribution with k = 3. For example, the probability of the mating combination (AA,aa) is 2 ft(AA)ft(aa) and it can only result in the Aa genotype: [0,1,0]. Overall, the resulting genotype frequencies are calculated as: As before, one can show that the allele frequencies at time t + 1 equal those at time t, and so, are constant in time. Similarly, the genotype frequencies depend only on the allele frequencies, and so, after time t = 1 are also constant in time. If in either monoecious or dioecious organisms, either the allele or genotype proportions are initially unequal in either sex, it can be shown that constant proportions are obtained after one generation of random mating. If dioecious organisms are heterogametic and the gene locus is located on the X chromosome, it can be shown that if the allele frequencies are initially unequal in the two sexes [e.g., XX females and XY males, as in humans], f′(a) in the heterogametic sex ''chases'' f(a) in the homogametic sex of the previous generation, until an equilibrium is reached at the weighted average of the two initial frequencies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Deviations from Hardy–Weinberg equilibrium', 'Violations of the Hardy–Weinberg assumptions can cause deviations from expectation. How this affects the population depends on the assumptions that are violated. Random mating. The HWP states the population will have the given genotypic frequencies (called Hardy–Weinberg proportions) after a single generation of random mating within the population. When the random mating assumption is violated, the population will not have Hardy–Weinberg proportions. A common cause of non-random mating is inbreeding, which causes an increase in homozygosity for all genes. If a population violates one of the following four assumptions, the population may continue to have Hardy–Weinberg proportions each generation, but the allele frequencies will change over time. Selection, in general, causes allele frequencies to change, often quite rapidly. While directional selection eventually leads to the loss of all alleles except the favored one (unless one allele is dominant, in which case recessive alleles can survive at low frequencies), some forms of selection, such as balancing selection, lead to equilibrium without loss of alleles. Mutation will have a very subtle effect on allele frequencies through the introduction of new allele into a population. Mutation rates are of the order 10−4 to 10−8, and the change in allele frequency will be, at most, the same order. Recurrent mutation will maintain alleles in the population, even if there is strong selection against them.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Violations of the Hardy–Weinberg assumptions can cause deviations from expectation. How this affects the population depends on the assumptions that are violated. Random mating. The HWP states the population will have the given genotypic frequencies (called Hardy–Weinberg proportions) after a single generation of random mating within the population. When the random mating assumption is violated, the population will not have Hardy–Weinberg proportions. A common cause of non-random mating is inbreeding, which causes an increase in homozygosity for all genes. If a population violates one of the following four assumptions, the population may continue to have Hardy–Weinberg proportions each generation, but the allele frequencies will change over time. Selection, in general, causes allele frequencies to change, often quite rapidly. While directional selection eventually leads to the loss of all alleles except the favored one (unless one allele is dominant, in which case recessive alleles can survive at low frequencies), some forms of selection, such as balancing selection, lead to equilibrium without loss of alleles. Mutation will have a very subtle effect on allele frequencies through the introduction of new allele into a population. Mutation rates are of the order 10−4 to 10−8, and the change in allele frequency will be, at most, the same order. Recurrent mutation will maintain alleles in the population, even if there is strong selection against them.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Deviations from Hardy–Weinberg equilibrium', 'Migration genetically links two or more populations together. In general, allele frequencies will become more homogeneous among the populations. Some models for migration inherently include nonrandom mating (Wahlund effect, for example). For those models, the Hardy–Weinberg proportions will normally not be valid. Small population size can cause a random change in allele frequencies. This is due to a sampling effect, and is called genetic drift. Sampling effects are most important when the allele is present in a small number of copies. In real world genotype data, deviations from Hardy–Weinberg Equilibrium may be a sign of genotyping error.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Migration genetically links two or more populations together. In general, allele frequencies will become more homogeneous among the populations. Some models for migration inherently include nonrandom mating (Wahlund effect, for example). For those models, the Hardy–Weinberg proportions will normally not be valid. Small population size can cause a random change in allele frequencies. This is due to a sampling effect, and is called genetic drift. Sampling effects are most important when the allele is present in a small number of copies. In real world genotype data, deviations from Hardy–Weinberg Equilibrium may be a sign of genotyping error.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Hardy–Weinberg principle: Sex linkage', 'Where the A gene is sex linked, the heterogametic sex (e.g., mammalian males; avian females) have only one copy of the gene (and are termed hemizygous), while the homogametic sex (e.g., human females) have two copies. The genotype frequencies at equilibrium are p and q for the heterogametic sex but p2, 2pq and q2 for the homogametic sex. For example, in humans red–green colorblindness is an X-linked recessive trait. In western European males, the trait affects about 1 in 12, (q = 0.083) whereas it affects about 1 in 200 females (0.005, compared to q2 = 0.007), very close to Hardy–Weinberg proportions. If a population is brought together with males and females with a different allele frequency in each subpopulation (males or females), the allele frequency of the male population in the next generation will follow that of the female population because each son receives its X chromosome from its mother. The population converges on equilibrium very quickly.', 'Wikipedia: Hardy–Weinberg principle', 'https://en.wikipedia.org/w/index.php?title=Hardy%E2%80%93Weinberg_principle&oldid=1367629467', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Where the A gene is sex linked, the heterogametic sex (e.g., mammalian males; avian females) have only one copy of the gene (and are termed hemizygous), while the homogametic sex (e.g., human females) have two copies. The genotype frequencies at equilibrium are p and q for the heterogametic sex but p2, 2pq and q2 for the homogametic sex. For example, in humans red–green colorblindness is an X-linked recessive trait. In western European males, the trait affects about 1 in 12, (q = 0.083) whereas it affects about 1 in 200 females (0.005, compared to q2 = 0.007), very close to Hardy–Weinberg proportions. If a population is brought together with males and females with a different allele frequency in each subpopulation (males or females), the allele frequency of the male population in the next generation will follow that of the female population because each son receives its X chromosome from its mother. The population converges on equilibrium very quickly.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection', 'Natural selection is the differential survival and reproduction of individuals due to differences in the relative fitness endowed on them by their own particular complement of observable characteristics. It is a key law or mechanism of evolution which changes the heritable traits characteristic of a population or species over generations. Charles Darwin popularised the term "natural selection", contrasting it with artificial selection, which is intentional, whereas natural selection is not. For Darwin, natural selection was a law or principle which resulted from three different kinds of process: inheritance, including the transmission of heritable material from parent to offspring and its development (ontogeny) in the offspring; variation, which partly resulted from an organism''s own agency; and the struggle for existence, which included both competition between organisms and cooperation or ''mutual aid'' (particularly in ''social'' plants and social animals).', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Natural selection is the differential survival and reproduction of individuals due to differences in the relative fitness endowed on them by their own particular complement of observable characteristics. It is a key law or mechanism of evolution which changes the heritable traits characteristic of a population or species over generations. Charles Darwin popularised the term "natural selection", contrasting it with artificial selection, which is intentional, whereas natural selection is not. For Darwin, natural selection was a law or principle which resulted from three different kinds of process: inheritance, including the transmission of heritable material from parent to offspring and its development (ontogeny) in the offspring; variation, which partly resulted from an organism''s own agency; and the struggle for existence, which included both competition between organisms and cooperation or ''mutual aid'' (particularly in ''social'' plants and social animals).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection', 'Variation of traits, both genotypic and phenotypic, exists within all populations of organisms. However, some traits are more likely to facilitate survival and reproductive success. Thus, these traits are more likely to be passed on to the next generation. These traits can also become more common within a population if the environment that favours these traits remains fixed. If new traits become more favoured due to changes in a specific niche, microevolution occurs. If new traits become more favoured due to changes in the broader environment, macroevolution occurs. Sometimes, new species can arise especially if these new traits are radically different from the traits possessed by their predecessors. The likelihood of these traits being ''selected'' and passed down is determined by many factors. Some are likely to be passed down because they adapt well to their environments. Others are passed down because these traits are actively preferred by mating partners, which is known as sexual selection. Female bodies also prefer traits that confer the lowest cost to their reproductive health, which is known as fecundity selection.', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Variation of traits, both genotypic and phenotypic, exists within all populations of organisms. However, some traits are more likely to facilitate survival and reproductive success. Thus, these traits are more likely to be passed on to the next generation. These traits can also become more common within a population if the environment that favours these traits remains fixed. If new traits become more favoured due to changes in a specific niche, microevolution occurs. If new traits become more favoured due to changes in the broader environment, macroevolution occurs. Sometimes, new species can arise especially if these new traits are radically different from the traits possessed by their predecessors. The likelihood of these traits being ''selected'' and passed down is determined by many factors. Some are likely to be passed down because they adapt well to their environments. Others are passed down because these traits are actively preferred by mating partners, which is known as sexual selection. Female bodies also prefer traits that confer the lowest cost to their reproductive health, which is known as fecundity selection.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection', 'Natural selection is a cornerstone of modern biology. The concept, published by Darwin and Alfred Russel Wallace in a joint presentation of papers in 1858, was elaborated in Darwin''s influential 1859 book On the Origin of Species by Means of Natural Selection, or the Preservation of Favoured Races in the Struggle for Life. He described natural selection as analogous to artificial selection, a process by which animals and plants with traits considered desirable by human breeders are systematically favoured for reproduction. The concept of natural selection originally developed in the absence of a valid theory of heredity; at the time of Darwin''s writing, science had yet to develop modern theories of genetics. The union of traditional Darwinian evolution with subsequent discoveries in classical genetics formed the modern synthesis of the mid-20th century. New evidence has prompted 21st century evolutionary biologists to challenge the 20th century''s gene-centred view of evolution, producing several extended evolutionary syntheses which bring organisms back to the heart of the theory of natural selection. Convergently, the growth of molecular genetics has led to evolutionary developmental biology, which compares the developmental processes of different organisms to infer how developmental processes evolved. While it is now recognised that genotypes can slowly change by random genetic drift, natural selection remains the primary explanation for adaptive evolution.', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Natural selection is a cornerstone of modern biology. The concept, published by Darwin and Alfred Russel Wallace in a joint presentation of papers in 1858, was elaborated in Darwin''s influential 1859 book On the Origin of Species by Means of Natural Selection, or the Preservation of Favoured Races in the Struggle for Life. He described natural selection as analogous to artificial selection, a process by which animals and plants with traits considered desirable by human breeders are systematically favoured for reproduction. The concept of natural selection originally developed in the absence of a valid theory of heredity; at the time of Darwin''s writing, science had yet to develop modern theories of genetics. The union of traditional Darwinian evolution with subsequent discoveries in classical genetics formed the modern synthesis of the mid-20th century. New evidence has prompted 21st century evolutionary biologists to challenge the 20th century''s gene-centred view of evolution, producing several extended evolutionary syntheses which bring organisms back to the heart of the theory of natural selection. Convergently, the growth of molecular genetics has led to evolutionary developmental biology, which compares the developmental processes of different organisms to infer how developmental processes evolved. While it is now recognised that genotypes can slowly change by random genetic drift, natural selection remains the primary explanation for adaptive evolution.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection: Pre-Darwinian theories', 'Several philosophers of the classical era, including Empedocles and his intellectual successor, the Roman poet Lucretius, expressed the idea that nature produces a huge variety of creatures, randomly, and that only those creatures that manage to provide for themselves and reproduce successfully persist. Empedocles'' idea that organisms arose entirely by the incidental workings of causes such as heat and cold was criticised by Aristotle in Book II of Physics. He posited natural teleology in its place, and believed that form was achieved for a purpose, citing the regularity of heredity in species as proof. Nevertheless, he accepted in his biology that new types of animals, monstrosities (τερας), can occur in very rare instances (Generation of Animals, Book IV). As quoted in Darwin''s 1872 edition of The Origin of Species, Aristotle considered whether different forms (e.g., of teeth) might have appeared accidentally, but only the useful forms survived:', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Several philosophers of the classical era, including Empedocles and his intellectual successor, the Roman poet Lucretius, expressed the idea that nature produces a huge variety of creatures, randomly, and that only those creatures that manage to provide for themselves and reproduce successfully persist. Empedocles'' idea that organisms arose entirely by the incidental workings of causes such as heat and cold was criticised by Aristotle in Book II of Physics. He posited natural teleology in its place, and believed that form was achieved for a purpose, citing the regularity of heredity in species as proof. Nevertheless, he accepted in his biology that new types of animals, monstrosities (τερας), can occur in very rare instances (Generation of Animals, Book IV). As quoted in Darwin''s 1872 edition of The Origin of Species, Aristotle considered whether different forms (e.g., of teeth) might have appeared accidentally, but only the useful forms survived:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection: Pre-Darwinian theories', 'So what hinders the different parts [of the body] from having this merely accidental relation in nature? as the teeth, for example, grow by necessity, the front ones sharp, adapted for dividing, and the grinders flat, and serviceable for masticating the food; since they were not made for the sake of this, but it was the result of accident. And in like manner as to the other parts in which there appears to exist an adaptation to an end. Wheresoever, therefore, all things together (that is all the parts of one whole) happened like as if they were made for the sake of something, these were preserved, having been appropriately constituted by an internal spontaneity, and whatsoever things were not thus constituted, perished, and still perish. But Aristotle rejected this possibility in the next paragraph, making clear that he is talking about the development of animals as embryos with the phrase "either invariably or normally come about", not the origin of species:', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'So what hinders the different parts [of the body] from having this merely accidental relation in nature? as the teeth, for example, grow by necessity, the front ones sharp, adapted for dividing, and the grinders flat, and serviceable for masticating the food; since they were not made for the sake of this, but it was the result of accident. And in like manner as to the other parts in which there appears to exist an adaptation to an end. Wheresoever, therefore, all things together (that is all the parts of one whole) happened like as if they were made for the sake of something, these were preserved, having been appropriately constituted by an internal spontaneity, and whatsoever things were not thus constituted, perished, and still perish. But Aristotle rejected this possibility in the next paragraph, making clear that he is talking about the development of animals as embryos with the phrase "either invariably or normally come about", not the origin of species:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection: Pre-Darwinian theories', '... Yet it is impossible that this should be the true view. For teeth and all other natural things either invariably or normally come about in a given way; but of not one of the results of chance or spontaneity is this true. We do not ascribe to chance or mere coincidence the frequency of rain in winter, but frequent rain in summer we do; nor heat in the dog-days, but only if we have it in winter. If then, it is agreed that things are either the result of coincidence or for an end, and these cannot be the result of coincidence or spontaneity, it follows that they must be for an end; and that such things are all due to nature even the champions of the theory which is before us would agree. Therefore action for an end is present in things which come to be and are by nature. The struggle for existence was later described by the Islamic writer Al-Jahiz in the 9th century, particularly in the context of top-down population regulation, but not in reference to individual variation or natural selection.', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = '... Yet it is impossible that this should be the true view. For teeth and all other natural things either invariably or normally come about in a given way; but of not one of the results of chance or spontaneity is this true. We do not ascribe to chance or mere coincidence the frequency of rain in winter, but frequent rain in summer we do; nor heat in the dog-days, but only if we have it in winter. If then, it is agreed that things are either the result of coincidence or for an end, and these cannot be the result of coincidence or spontaneity, it follows that they must be for an end; and that such things are all due to nature even the champions of the theory which is before us would agree. Therefore action for an end is present in things which come to be and are by nature. The struggle for existence was later described by the Islamic writer Al-Jahiz in the 9th century, particularly in the context of top-down population regulation, but not in reference to individual variation or natural selection.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection: Pre-Darwinian theories', 'At the turn of the 16th century Leonardo da Vinci collected a set of fossils of ammonites as well as other biological material. He extensively reasoned in his writings that the shapes of animals are not given once and forever by the "upper power" but instead are generated in different forms naturally and then selected for reproduction by their compatibility with the environment. The more recent classical arguments were reintroduced in the 18th century by Pierre Louis Maupertuis and others, including Darwin''s grandfather, Erasmus Darwin. Until the early 19th century, the prevailing view in Western societies was that differences between individuals of a species were uninteresting departures from their Platonic ideals (or typus) of created kinds. However, the theory of uniformitarianism in geology promoted the idea that simple, weak forces could act continuously over long periods of time to produce radical changes in the Earth''s landscape. The success of this theory raised awareness of the vast scale of geological time and made plausible the idea that tiny, virtually imperceptible changes in successive generations could produce consequences on the scale of differences between species.', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'At the turn of the 16th century Leonardo da Vinci collected a set of fossils of ammonites as well as other biological material. He extensively reasoned in his writings that the shapes of animals are not given once and forever by the "upper power" but instead are generated in different forms naturally and then selected for reproduction by their compatibility with the environment. The more recent classical arguments were reintroduced in the 18th century by Pierre Louis Maupertuis and others, including Darwin''s grandfather, Erasmus Darwin. Until the early 19th century, the prevailing view in Western societies was that differences between individuals of a species were uninteresting departures from their Platonic ideals (or typus) of created kinds. However, the theory of uniformitarianism in geology promoted the idea that simple, weak forces could act continuously over long periods of time to produce radical changes in the Earth''s landscape. The success of this theory raised awareness of the vast scale of geological time and made plausible the idea that tiny, virtually imperceptible changes in successive generations could produce consequences on the scale of differences between species.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Natural selection: Pre-Darwinian theories', 'The early 19th-century zoologist Jean-Baptiste Lamarck suggested the inheritance of acquired characteristics as a mechanism for evolutionary change; adaptive traits acquired by an organism during its lifetime could be inherited by that organism''s progeny, eventually causing transmutation of species. This theory, Lamarckism, was an influence on the Soviet biologist Trofim Lysenko''s ill-fated antagonism to mainstream genetic theory as late as the mid-20th century. Between 1835 and 1837, the zoologist Edward Blyth worked on the area of variation, artificial selection, and how a similar process occurs in nature. Darwin acknowledged Blyth''s ideas in the first chapter on variation of On the Origin of Species.', 'Wikipedia: Natural selection', 'https://en.wikipedia.org/w/index.php?title=Natural_selection&oldid=1381515893', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'The early 19th-century zoologist Jean-Baptiste Lamarck suggested the inheritance of acquired characteristics as a mechanism for evolutionary change; adaptive traits acquired by an organism during its lifetime could be inherited by that organism''s progeny, eventually causing transmutation of species. This theory, Lamarckism, was an influence on the Soviet biologist Trofim Lysenko''s ill-fated antagonism to mainstream genetic theory as late as the mid-20th century. Between 1835 and 1837, the zoologist Edward Blyth worked on the area of variation, artificial selection, and how a similar process occurs in nature. Darwin acknowledged Blyth''s ideas in the first chapter on variation of On the Origin of Species.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift', 'Genetic drift is the change in the frequency of an existing allele in a population due to chance. Genetic drift may cause alleles to disappear completely and thereby reduce genetic variation. It can also cause initially rare alleles to become much more frequent possibly leading to fixation where the initially rare allele displaces all others. In the middle of the 20th century, vigorous debates occurred over the relative importance of natural selection versus neutral processes, including genetic drift. Ronald Fisher, who explained natural selection using Mendelian genetics, held the view that genetic drift plays at most a minor role in evolution, and this remained the dominant view for several decades. In 1968, population geneticist Motoo Kimura rekindled the debate with his neutral theory of molecular evolution, which claims that most instances where a genetic change spreads across a population (although not necessarily changes in phenotypes) are caused by genetic drift acting on neutral mutations.', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Genetic drift is the change in the frequency of an existing allele in a population due to chance. Genetic drift may cause alleles to disappear completely and thereby reduce genetic variation. It can also cause initially rare alleles to become much more frequent possibly leading to fixation where the initially rare allele displaces all others. In the middle of the 20th century, vigorous debates occurred over the relative importance of natural selection versus neutral processes, including genetic drift. Ronald Fisher, who explained natural selection using Mendelian genetics, held the view that genetic drift plays at most a minor role in evolution, and this remained the dominant view for several decades. In 1968, population geneticist Motoo Kimura rekindled the debate with his neutral theory of molecular evolution, which claims that most instances where a genetic change spreads across a population (although not necessarily changes in phenotypes) are caused by genetic drift acting on neutral mutations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Analogy with marbles in a jar', 'The process of genetic drift can be illustrated using 20 marbles in a jar to represent 20 organisms in a population. Consider that jar of marbles as the starting population. Half of the marbles in the jar are red and half are blue, with each colour corresponding to a different allele of one gene in the population. In each new generation, the organisms reproduce at random. To represent this reproduction, randomly select a marble from the original jar and deposit a new marble with the same colour into a new jar. This is the "offspring" of the original marble, meaning that the original marble remains in its jar. Repeat this process until 20 new marbles are in the second jar. The second jar will now contain 20 "offspring", or marbles of various colours. Unless the second jar contains exactly 10 red marbles and 10 blue marbles, a random shift has occurred in the allele frequencies.', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'The process of genetic drift can be illustrated using 20 marbles in a jar to represent 20 organisms in a population. Consider that jar of marbles as the starting population. Half of the marbles in the jar are red and half are blue, with each colour corresponding to a different allele of one gene in the population. In each new generation, the organisms reproduce at random. To represent this reproduction, randomly select a marble from the original jar and deposit a new marble with the same colour into a new jar. This is the "offspring" of the original marble, meaning that the original marble remains in its jar. Repeat this process until 20 new marbles are in the second jar. The second jar will now contain 20 "offspring", or marbles of various colours. Unless the second jar contains exactly 10 red marbles and 10 blue marbles, a random shift has occurred in the allele frequencies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Analogy with marbles in a jar', 'If this process is repeated a number of times, the numbers of red and blue marbles picked each generation fluctuates. Sometimes, a jar has more red marbles than its "parent" jar and sometimes more blue. This fluctuation is analogous to genetic drift – a change in the population''s allele frequency resulting from a random variation in the distribution of alleles from one generation to the next. In any one generation, no marbles of a particular colour could be chosen, meaning they have no offspring. In this example, if no red marbles are selected, the jar representing the new generation contains only blue offspring. If this happens, the red allele has been lost permanently in the population, while the remaining blue allele has become fixed: all future generations are entirely blue. In small populations, fixation can occur in just a few generations.', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'If this process is repeated a number of times, the numbers of red and blue marbles picked each generation fluctuates. Sometimes, a jar has more red marbles than its "parent" jar and sometimes more blue. This fluctuation is analogous to genetic drift – a change in the population''s allele frequency resulting from a random variation in the distribution of alleles from one generation to the next. In any one generation, no marbles of a particular colour could be chosen, meaning they have no offspring. In this example, if no red marbles are selected, the jar representing the new generation contains only blue offspring. If this happens, the red allele has been lost permanently in the population, while the remaining blue allele has become fixed: all future generations are entirely blue. In small populations, fixation can occur in just a few generations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Probability and allele frequency', 'The mechanisms of genetic drift can be illustrated with a simple example. Consider a very large colony of bacteria isolated in a drop of solution. The bacteria are genetically identical except for a single gene with two alleles labeled A and B, which are neutral alleles, meaning that they do not affect the bacteria''s ability to survive and reproduce; all bacteria in this colony are equally likely to survive and reproduce. Suppose that half the bacteria have allele A and the other half have allele B. Thus, A and B each has an allele frequency of 1/2. The drop of solution then shrinks until it has only enough food to sustain four bacteria. All other bacteria die without reproducing. Among the four that survive, 16 possible combinations for the A and B alleles exist: (A-A-A-A), (B-A-A-A), (A-B-A-A), (B-B-A-A), (A-A-B-A), (B-A-B-A), (A-B-B-A), (B-B-B-A), (A-A-A-B), (B-A-A-B), (A-B-A-B), (B-B-A-B), (A-A-B-B), (B-A-B-B), (A-B-B-B), (B-B-B-B). Since all bacteria in the original solution are equally likely to survive when the solution shrinks, the four survivors are a random sample from the original colony. The probability that each of the four survivors has a given allele is 1/2, and so the probability that any particular allele combination occurs when the solution shrinks is', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'The mechanisms of genetic drift can be illustrated with a simple example. Consider a very large colony of bacteria isolated in a drop of solution. The bacteria are genetically identical except for a single gene with two alleles labeled A and B, which are neutral alleles, meaning that they do not affect the bacteria''s ability to survive and reproduce; all bacteria in this colony are equally likely to survive and reproduce. Suppose that half the bacteria have allele A and the other half have allele B. Thus, A and B each has an allele frequency of 1/2. The drop of solution then shrinks until it has only enough food to sustain four bacteria. All other bacteria die without reproducing. Among the four that survive, 16 possible combinations for the A and B alleles exist: (A-A-A-A), (B-A-A-A), (A-B-A-A), (B-B-A-A), (A-A-B-A), (B-A-B-A), (A-B-B-A), (B-B-B-A), (A-A-A-B), (B-A-A-B), (A-B-A-B), (B-B-A-B), (A-A-B-B), (B-A-B-B), (A-B-B-B), (B-B-B-B). Since all bacteria in the original solution are equally likely to survive when the solution shrinks, the four survivors are a random sample from the original colony. The probability that each of the four survivors has a given allele is 1/2, and so the probability that any particular allele combination occurs when the solution shrinks is');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Probability and allele frequency', '(The original population size is so large that the sampling effectively happens with replacement). In other words, each of the 16 possible allele combinations is equally likely to occur, with probability 1/16. Counting the combinations with the same number of A and B gives the following table: As shown in the table, the total number of combinations that have the same number of A alleles as of B alleles is six, and the probability of this combination is 6/16. The total number of other combinations is ten, so the probability of unequal number of A and B alleles is 10/16. Thus, although the original colony began with an equal number of A and B alleles, quite possibly, the number of alleles in the remaining population of four members will not be equal. The situation of equal numbers is actually less likely than unequal numbers. In the latter case, genetic drift has occurred because the population''s allele frequencies have changed due to random sampling. In this example, the population contracted to just four random survivors, a phenomenon known as a population bottleneck.', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = '(The original population size is so large that the sampling effectively happens with replacement). In other words, each of the 16 possible allele combinations is equally likely to occur, with probability 1/16. Counting the combinations with the same number of A and B gives the following table: As shown in the table, the total number of combinations that have the same number of A alleles as of B alleles is six, and the probability of this combination is 6/16. The total number of other combinations is ten, so the probability of unequal number of A and B alleles is 10/16. Thus, although the original colony began with an equal number of A and B alleles, quite possibly, the number of alleles in the remaining population of four members will not be equal. The situation of equal numbers is actually less likely than unequal numbers. In the latter case, genetic drift has occurred because the population''s allele frequencies have changed due to random sampling. In this example, the population contracted to just four random survivors, a phenomenon known as a population bottleneck.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Probability and allele frequency', 'The probabilities for the number of copies of allele A (or B) that survive (given in the last column of the above table) can be calculated directly from the binomial distribution, where the "success" probability (probability of a given allele being present) is 1/2 (i.e., the probability that there are k copies of A (or B) alleles in the combination) is given by:', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
