insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Mathematical models', 'Mathematical models of genetic drift can be designed using either branching processes or a diffusion equation describing changes in allele frequency in an idealised population.', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Mathematical models of genetic drift can be designed using either branching processes or a diffusion equation describing changes in allele frequency in an idealised population.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'genetics-evolution', 'Genetic drift: Wright–Fisher model', 'Consider a gene with two alleles, A or B. In diploidy, populations consisting of N individuals have 2N copies of each gene. An individual can have two copies of the same allele or two different alleles. The frequency of one allele is assigned p and the other q. The Wright–Fisher model (named after Sewall Wright and Ronald Fisher) assumes that generations do not overlap (for example, annual plants have exactly one generation per year) and that each copy of the gene found in the new generation is drawn independently at random from all copies of the gene in the old generation. The formula to calculate the probability of obtaining k copies of an allele that had frequency p in the last generation is then where the symbol "!" signifies the factorial function. This expression can also be formulated using the binomial coefficient,', 'Wikipedia: Genetic drift', 'https://en.wikipedia.org/w/index.php?title=Genetic_drift&oldid=1364511177', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'genetics-evolution' and body = 'Consider a gene with two alleles, A or B. In diploidy, populations consisting of N individuals have 2N copies of each gene. An individual can have two copies of the same allele or two different alleles. The frequency of one allele is assigned p and the other q. The Wright–Fisher model (named after Sewall Wright and Ronald Fisher) assumes that generations do not overlap (for example, annual plants have exactly one generation per year) and that each copy of the gene found in the new generation is drawn independently at random from all copies of the gene in the old generation. The formula to calculate the probability of obtaining k copies of an allele that had frequency p in the last generation is then where the symbol "!" signifies the factorial function. This expression can also be formulated using the binomial coefficient,');
